import type {FC} from 'react';
import React from 'react';

import {Icon} from '@gravity-ui/uikit';

import {cnIconRefuge} from './IconRefuge.classname';
import type {IconRefugeProps} from './types';

import './IconRefuge.scss';

/**
 * Creates a div wrapper around icon with min-width и min-height
 * equal to the prop refugeSize, puts the original icon in the center and
 * proxies the rest of the props to it.
 */
export const IconRefuge: FC<IconRefugeProps> = ({
    refugeSize,
    containerClassName,
    containerStyle,
    widthOnly,
    inlineIcon,
    title,
    'aria-label': ariaLabel = title,
    ...props
}) => {
    if (props.size === refugeSize && !title && !ariaLabel && !containerStyle) {
        return <Icon {...props} />;
    }

    return (
        <div
            className={cnIconRefuge({inline: inlineIcon}, containerClassName)}
            style={{
                minWidth: refugeSize,
                minHeight: widthOnly ? undefined : refugeSize,
                ...containerStyle,
            }}
        >
            <Icon size={refugeSize} {...props} />
            {ariaLabel && <span className={cnIconRefuge('hidden-label')}>{ariaLabel}</span>}
        </div>
    );
};

// so the common/Button considers Refuge an icon
IconRefuge.displayName = 'Icon';
